function validate([bloomDay, m, k]) {
  if (!Array.isArray(bloomDay) || bloomDay.length < 1 || bloomDay.length > 100000) return 'bloomDay needs 1 to 10^5 values.';
  if (bloomDay.some(d => !Number.isInteger(d) || d < 1 || d > 1e9)) return 'Each bloom day is a whole number from 1 to 10^9.';
  if (!Number.isInteger(m) || m < 1 || m > 1e6) return 'm is a whole number from 1 to 10^6.';
  if (!Number.isInteger(k) || k < 1 || k > bloomDay.length) return 'k is between 1 and the number of flowers.';
  return null;
}

