function minDays(bloomDay, m, k) {
  if (m * k > bloomDay.length) {
    return -1;
  }
  let low = 1;
  let high = Math.max(...bloomDay);

  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    let bouquets = 0;
    let streak = 0;
    for (const day of bloomDay) {
      if (day <= mid) {
        streak++;
        if (streak === k) {
          bouquets++;
          streak = 0;
        }
      } else {
        streak = 0;
      }
    }
    if (bouquets >= m) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

