function minDays(bloomDay, m, k) {
  const days = [...new Set(bloomDay)].sort((a, b) => a - b);
  for (const d of days) {
    let made = 0, run = 0;
    for (let i = 0; i <= bloomDay.length; i++) {
      if (i < bloomDay.length && bloomDay[i] <= d) run++;
      else { made += Math.floor(run / k); run = 0; }
    }
    if (made >= m) return d;
  }
  return -1;
}

