function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const high = rand() < 0.5 ? 1000000000 : 50;
    const bloomDay = Array.from({ length: n }, () => pick(1, high));
    const k = pick(1, 6);
    const m = rand() < 0.15 ? pick(Math.floor(n / k) + 1, 1000000) : pick(1, Math.floor(n / k));
    return [bloomDay, m, k];
  }
  const n = pick(1, 8);
  const high = rand() < 0.5 ? 4 : 15;
  const bloomDay = Array.from({ length: n }, () => pick(1, high));
  const k = pick(1, n);
  const m = pick(1, 4);
  return [bloomDay, m, k];
}
